 check_expression:=replace(check_expression,'user_has_clearview_access(', 'user_has_clearview_access_e28_private(');
 expression:=regexp_replace(expression, '(public\.)?has_role\(auth.uid\(\), ''uno_team''(::app_role)?\)', 'false','g');
